#!/usr/bin/env bash
set -e

ZIG_VERSION="0.15.2"
ZIG_DIR="$HOME/.local/zig"
ZIG_BIN="$ZIG_DIR/zig"

if [ -f "$ZIG_BIN" ]; then
  INSTALLED=$("$ZIG_BIN" version 2>/dev/null || echo "")
  if [ "$INSTALLED" = "$ZIG_VERSION" ]; then
    exit 0
  fi
fi

ARCH=$(uname -m)
case "$ARCH" in
  x86_64)  ZIG_ARCH="x86_64" ;;
  aarch64) ZIG_ARCH="aarch64" ;;
  armv7*)  ZIG_ARCH="arm" ;;
  *)
    echo "Unsupported architecture: $ARCH"
    exit 1
    ;;
esac

ZIG_TARBALL="zig-${ZIG_ARCH}-linux-${ZIG_VERSION}.tar.xz"
ZIG_URL="https://ziglang.org/download/${ZIG_VERSION}/${ZIG_TARBALL}"
ZIG_EXTRACTED="zig-${ZIG_ARCH}-linux-${ZIG_VERSION}"

TMP_DIR=$(mktemp -d)
trap 'rm -rf "$TMP_DIR"' EXIT

echo "Downloading Zig ${ZIG_VERSION} for ${ZIG_ARCH}..."
curl -fsSL "$ZIG_URL" -o "$TMP_DIR/$ZIG_TARBALL"

echo "Extracting..."
tar -xf "$TMP_DIR/$ZIG_TARBALL" -C "$TMP_DIR"

rm -rf "$ZIG_DIR"
mkdir -p "$ZIG_DIR"
cp -r "$TMP_DIR/$ZIG_EXTRACTED/." "$ZIG_DIR/"
chmod +x "$ZIG_BIN"

echo "Zig $("$ZIG_BIN" version) installed at $ZIG_BIN"




