bash
#!/usr/bin/env bash
set -e

ZIG_VERSION="0.15.2"
ZIG_DIR="$HOME/.local/zig"
ZIG_BIN="$ZIG_DIR/zig"

install_zig() {
  ARCH=$(uname -m)
  case "$ARCH" in
    x86_64)  ZIG_ARCH="x86_64" ;;
    aarch64) ZIG_ARCH="aarch64" ;;
    armv7*)  ZIG_ARCH="arm" ;;
    *)
      echo "Unsupported architecture: $ARCH"
      exit 1
      ;;
  esac

  ZIG_TARBALL="zig-${ZIG_ARCH}-linux-${ZIG_VERSION}.tar.xz"
  ZIG_URL="https://ziglang.org/download/${ZIG_VERSION}/${ZIG_TARBALL}"
  ZIG_EXTRACTED="zig-${ZIG_ARCH}-linux-${ZIG_VERSION}"

  TMP_DIR=$(mktemp -d)
  trap 'rm -rf "$TMP_DIR"' EXIT

  echo "[zig-install] Downloading Zig ${ZIG_VERSION} (${ZIG_ARCH}-linux)..."
  curl -fsSL --retry 3 --retry-delay 2 "$ZIG_URL" -o "$TMP_DIR/$ZIG_TARBALL"

  echo "[zig-install] Extracting..."
  tar -xf "$TMP_DIR/$ZIG_TARBALL" -C "$TMP_DIR"

  rm -rf "$ZIG_DIR"
  mkdir -p "$ZIG_DIR"
  cp -r "$TMP_DIR/$ZIG_EXTRACTED/." "$ZIG_DIR/"
  chmod +x "$ZIG_BIN"

  echo "[zig-install] Zig $("$ZIG_BIN" version) ready at $ZIG_BIN"
}

if [ ! -f "$ZIG_BIN" ]; then
  install_zig
else
  INSTALLED=$("$ZIG_BIN" version 2>/dev/null || echo "")
  if [ "$INSTALLED" != "$ZIG_VERSION" ]; then
    echo "[zig-install] Version mismatch ($INSTALLED != $ZIG_VERSION), reinstalling..."
    install_zig
  else
    echo "[zig] Zig ${ZIG_VERSION} already installed, skipping download."
  fi
fi

export PATH="$ZIG_DIR:$PATH"

echo "[zig] Building with ReleaseFast + LTO..."
exec "$ZIG_BIN" build run -Doptimize=ReleaseFast --prominent-compile-errors




